parameters.functionCode:
// Create Zoom meeting
const appointment = items[0].json;

const meetingData = {
  topic: `Telemedicine Visit - ${appointment.patient_first_name} ${appointment.patient_last_name}`,
  type: 2,
  start_time: `${appointment.appointment_date}T${appointment.appointment_time}`,
  duration: appointment.duration,
  settings: {
    host_video: true,
    participant_video: true,
    waiting_room: true,
    join_before_host: false,
    mute_upon_entry: true,
    auto_recording: 'cloud'
  }
};

return [{
  json: {
    ...appointment,
    meetingData
  }
}];

